        expect(screen.queryByText(/changed outside the editor/u)).not.toBeInTheDocument()
        expect(labelInput().value).toBe('Local edit')
    })

    it('does not remount the editor or lose focus on a successful save', async () => {
        vi.useFakeTimers()
